import axios from 'axios';
import React, { useEffect, useState } from 'react';
import FileBase64 from 'react-file-base64';
import { setProfile, getProfile } from '../utils/APIRoutes';

export default function Test() {
  const [item, setItem] = useState({ title: '', image: '' });
  const [items, setItems] = useState([]);

  const onSubmitHandler = async (e) => {
    e.preventDefault();
    const res = await axios.post(setProfile, item);
  };

  const getMe = async () => {
    const result = await axios.post(getProfile);
    if (result) {
      setItems(result);
    }
    console.log(items);
  };
  return (
    <div>
      <input
        type="text"
        name=""
        onChange={(e) => setItem({ ...item, title: e.target.value })}
      />
      <FileBase64
        type="file"
        multiple={false}
        onDone={({ base64 }) => setItem({ ...item, image: base64 })}
      />
      <button onClick={(e) => onSubmitHandler(e)}>Sub</button>
      <button onClick={(e) => getMe()}>get</button>

      {items?.map((item) => (
        <div className="card" key={item._id}>
          <img
            className="activator"
            style={{ width: '100%', height: 300 }}
            src={item.image}
            alt="nonthi"
          />
          <div className="card-content">
            <span className="card-title activator grey-text text-darken-4">
              {item.title}
            </span>
          </div>
        </div>
      ))}
    </div>
  );
}
